<script setup lang="ts">
import { inject, computed } from 'vue'; import { floatKey } from './float-context';
import './styles/theme.css'; import './styles/float-button.css';
const props = withDefaults(defineProps<{ description?: string; shape?: 'circle' | 'square'; type?: 'default' | 'primary'; htmlType?: 'button' | 'submit' | 'reset'; tooltip?: string; href?: string; target?: string; badge?: { count?: number; dot?: boolean; overflowCount?: number }; inline?: boolean; disabled?: boolean }>(), { type: 'default', htmlType: 'button', inline: undefined });
const group = inject(floatKey, null); const shape = computed(() => props.shape ?? group?.shape ?? 'circle'); const inline = computed(() => props.inline ?? group?.inline ?? false);
</script>
<template><component :is="href ? 'a' : 'button'" :href="disabled ? undefined : href" :target="target" :rel="target === '_blank' ? 'noreferrer' : undefined" :type="href ? undefined : htmlType" :disabled="disabled" :aria-disabled="disabled || undefined" :class="['at-float-button', `at-float-button--${shape}`, `at-float-button--${type}`, { 'at-float-button--inline': inline, 'at-float-button--with-description': description }]" :title="tooltip" :aria-label="tooltip ?? description"><span class="at-float-button__body"><span class="at-float-button__icon"><slot name="icon"><slot>↑</slot></slot></span><span v-if="description" class="at-float-button__description">{{ description }}</span></span><span v-if="badge && (badge.dot || (badge.count ?? 0) > 0)" :class="['at-float-button__badge', { 'at-float-button__badge--dot': badge.dot }]" aria-hidden="true">{{ badge.dot ? '' : (badge.count ?? 0) > (badge.overflowCount ?? 99) ? `${badge.overflowCount ?? 99}+` : badge.count }}</span></component></template>
